import { ACA_2027_PARAMETERS, HSA_2027_LIMITS, TAX_YEAR_2027_REVIEWED_AT } from '../tax-rules/tax-year-2027';

/** Reviewed guidance packets, not a complete tax-code retrieval system. */
export interface GuidanceSource {
  id: string;
  title: string;
  url: string;
  reviewedAt: string;
  supportedTaxYears: readonly number[];
  /** Model-facing routing summary; the model selects a packet, it never writes the answer. */
  summary: string;
  /** Follow-up questions the model may select as missing facts (ids are `${topic}:${index}`). */
  requiredFacts: readonly string[];
  /** Server-authored plain-English answer for a selectable topic. Year-dependent amounts use a function. */
  answer?: string | ((taxYear: number) => string);
  /** Where the item is reported: Schedule C line, Schedule 1, Schedule A, or "not deductible". */
  placement?: string;
  /** Records that support the position. */
  records?: readonly string[];
  /** Additional GUIDANCE_SOURCES ids cited with the answer (the topic's own source is always cited). */
  citations?: readonly string[];
}

/**
 * Closed set of topics the model may select. Everything the user reads is composed on the server
 * from the packet with the same id; the model only routes and picks missing-fact ids.
 */
